module.exports = "<section class=\"bmb_search-card\">\n  <bmb-home-card\n    [componentTitle]=\"\n      componentTitle() || title() || 'search_card.title' | translate\n    \"\n    [showRightButton]=\"false\"\n    icon=\"search\"\n    bgIconAppearance=\"blue-primary\"\n  >\n    <bmb-input\n      [placeholder]=\"\n        inputPlaceholder() || 'search_card.input_placeholder' | translate\n      \"\n      [icon]=\"'search'\"\n      [isClearable]=\"true\"\n      [control]=\"inputSearchControl\"\n      [isLoading]=\"isLoading()\"\n    />\n    <bmb-tabs [tabs]=\"tabsData()\" [(selectedTabId)]=\"selectedTabId\">\n      @switch (selectedTabId()) {\n        @case (1) {\n          <div class=\"bmb_search-card-results\">\n            @if (computedResults().services.length) {\n              <section class=\"bmb_search-card-results-section\">\n                <h3>{{ 'search_card.tabs.services' | translate }}</h3>\n                <ul class=\"bmb_search-card-results-list\">\n                  @for (service of computedResults().services; track $index) {\n                    <ng-container\n                      *ngTemplateOutlet=\"cardItem; context: { item: service }\"\n                    ></ng-container>\n                  }\n                </ul>\n              </section>\n            }\n            @if (computedResults().persons.length) {\n              <section class=\"bmb_search-card-results-section\">\n                <h3>{{ 'search_card.tabs.people' | translate }}</h3>\n                <ul class=\"bmb_search-card-results-list\">\n                  @for (person of computedResults().persons; track $index) {\n                    <ng-container\n                      *ngTemplateOutlet=\"cardItem; context: { item: person }\"\n                    ></ng-container>\n                  }\n                </ul>\n              </section>\n            }\n            @if (\n              !computedResults().services.length &&\n              !computedResults().persons.length\n            ) {\n              <bmb-search-card-empty-state\n                [inputHasValue]=\"!!inputSearchControl.value\"\n              ></bmb-search-card-empty-state>\n            }\n          </div>\n        }\n        @case (2) {\n          <div class=\"bmb_search-card-results\">\n            @if (computedResults().services.length) {\n              <section class=\"bmb_search-card-results-section\">\n                <h3>{{ 'search_card.tabs.services' | translate }}</h3>\n                <ul class=\"bmb_search-card-results-list\">\n                  @for (service of computedResults().services; track $index) {\n                    <ng-container\n                      *ngTemplateOutlet=\"cardItem; context: { item: service }\"\n                    ></ng-container>\n                  }\n                </ul>\n              </section>\n            } @else {\n              <bmb-search-card-empty-state\n                [inputHasValue]=\"!!inputSearchControl.value\"\n              ></bmb-search-card-empty-state>\n            }\n          </div>\n        }\n        @case (3) {\n          <div class=\"bmb_search-card-results\">\n            @if (computedResults().persons.length) {\n              <section class=\"bmb_search-card-results-section\">\n                <h3>{{ 'search_card.tabs.people' | translate }}</h3>\n                <ul class=\"bmb_search-card-results-list\">\n                  @for (person of computedResults().persons; track $index) {\n                    <ng-container\n                      *ngTemplateOutlet=\"cardItem; context: { item: person }\"\n                    ></ng-container>\n                  }\n                </ul>\n              </section>\n            } @else {\n              <bmb-search-card-empty-state\n                [inputHasValue]=\"!!inputSearchControl.value\"\n              ></bmb-search-card-empty-state>\n            }\n          </div>\n        }\n      }\n    </bmb-tabs>\n    {{ isLoading() ? 'Loading...' : '' }}\n  </bmb-home-card>\n</section>\n\n<ng-template #cardItem let-item=\"item\">\n  <li class=\"bmb_search-card-results-list-item\">\n    <bmb-search-card-item\n      [name]=\"item.name\"\n      [subtitle]=\"item.subtitle\"\n      [icon]=\"item.avatarOrIcon\"\n      [isService]=\"item.type === 'service'\"\n      [isBookmarkActive]=\"item.isBookmarkActive ?? false\"\n      (triggerClick)=\"searchItemClick.emit(item)\"\n      (getBookmarkClick)=\"handleBookmarkClick(item)\"\n    ></bmb-search-card-item>\n  </li>\n</ng-template>\n";

